// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title ConstantesUBO — Valores comunes a los tres módulos de Sello Libertador
/// @notice Uso: import "../comun/ConstantesUBO.sol";  y luego ConstantesUBO.ING
library ConstantesUBO {
    // ---------------------------------------------------------------
    // Facultades de la Universidad Bernardo O'Higgins
    // ---------------------------------------------------------------
    bytes32 internal constant ING = keccak256("ING"); // Ingeniería, Ciencia y Tecnología
    bytes32 internal constant HUM = keccak256("HUM"); // Ciencias Humanas
    bytes32 internal constant SAL = keccak256("SAL"); // Ciencias de la Salud
    bytes32 internal constant MED = keccak256("MED"); // Ciencias Médicas

    // ---------------------------------------------------------------
    // Códigos de motivo de suspensión o revocación (campo Titulo.motivo)
    // ---------------------------------------------------------------
    uint8 internal constant MOTIVO_NINGUNO = 0;
    uint8 internal constant MOTIVO_ERROR_ADMINISTRATIVO = 1;
    uint8 internal constant MOTIVO_FRAUDE = 2;
    uint8 internal constant MOTIVO_RESOLUCION_JUDICIAL = 3;
    uint8 internal constant MOTIVO_RECTIFICACION = 4;
    uint8 internal constant MOTIVO_EN_INVESTIGACION = 5; // típico de una suspensión

    // ---------------------------------------------------------------
    // Límites
    // ---------------------------------------------------------------
    /// @notice Máximo de títulos por llamada a emitirLote (evita DoS por límite de gas).
    uint256 internal constant MAX_LOTE = 50;

    /// @notice ¿Es una facultad reconocida?
    function esFacultadValida(bytes32 facultad) internal pure returns (bool) {
        return facultad == ING || facultad == HUM || facultad == SAL || facultad == MED;
    }

    /// @notice Compromiso criptográfico común a todo el sistema.
    /// @param sal           32 bytes aleatorios, incluidos en el documento cifrado del enlace.
    /// @param hashDocumento keccak256 del documento de la credencial en JSON
    ///                      canonicalizado (RFC 8785).
    function compromiso(bytes32 sal, bytes32 hashDocumento) internal pure returns (bytes32) {
        return keccak256(abi.encode(sal, hashDocumento));
    }

    /// @notice Hoja del árbol de Merkle de una ceremonia (ver IAnclajeLotes).
    function hojaLote(bytes10 localizador, bytes32 compromiso_) internal pure returns (bytes32) {
        return keccak256(bytes.concat(keccak256(abi.encode(localizador, compromiso_))));
    }
}

contracts/moduloC/HerramientasSello.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../interfaces/IHerramientasSello.sol";
import "../comun/ConstantesUBO.sol";

/// @title HerramientasSello — PLANTILLA del Módulo C (Curso C)
/// @notice Cálculos auxiliares en Solidity. Todas las funciones son `pure`: se pueden
///         llamar gratis desde «Deploy & Run» de Remix, sin enviar transacciones.
/// @dev    Completar los TODO. Las tres últimas funciones ya están hechas.
contract HerramientasSello is IHerramientasSello {
    error ByteNoAceptado(uint8 b);
    error ListaVacia();

    /// @dev Los 36 símbolos permitidos, en orden. ALFABETO[i] devuelve el símbolo número i.
    bytes internal constant ALFABETO = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";

    // ---------------------------------------------------------------
    // Localizador sin sesgo de módulo
    // ---------------------------------------------------------------
    /// @dev 256 = 7 × 36 + 4. El mayor múltiplo de 36 que cabe en 256 es 252 (7 × 36),
    ///      así que se aceptan los bytes 0..251: cada símbolo recibe exactamente 7 bytes.
    function byteAceptado(uint8 b) public pure override returns (bool) {
        return b < 252;
    }

    function simboloDe(uint8 b) public pure override returns (bytes1) {
        if (!byteAceptado(b)) revert ByteNoAceptado(b);
        return ALFABETO[b % 36];
    }

    function derivarLocalizador(bytes32 semilla) external pure override returns (bytes10) {
        bytes memory resultado = new bytes(10);
        uint256 n = 0;
        bytes32 h = keccak256(abi.encode(semilla));
        while (n < 10) {
            for (uint256 i = 0; i < 32 && n < 10; i++) {
                uint8 b = uint8(h[i]);
                if (byteAceptado(b)) {
                    resultado[n++] = simboloDe(b);
                }
            }
            if (n < 10) h = keccak256(abi.encode(h));
        }
        return bytes10(resultado);
    }

    // ---------------------------------------------------------------
    // Raíz de Merkle
    // ---------------------------------------------------------------
    /// @dev Reduce nivel a nivel sobre la misma copia en memoria: el nodo i del nivel
    ///      siguiente se escribe en la posición i, que ya fue leída. Si sobra un nodo,
    ///      sube tal cual.
    function raizDeMerkle(bytes32[] calldata hojas) external pure override returns (bytes32) {
        uint256 n = hojas.length;
        if (n == 0) revert ListaVacia();
        bytes32[] memory nivel = hojas;
        while (n > 1) {
            uint256 m = 0;
            for (uint256 i = 0; i < n; i += 2) {
                nivel[m++] = i + 1 < n ? _hashPar(nivel[i], nivel[i + 1]) : nivel[i];
            }
            n = m;
        }
        return nivel[0];
    }

    /// @dev Hash de un par ordenado, igual que MerkleProof de OpenZeppelin. YA HECHA.
    function _hashPar(bytes32 a, bytes32 b) internal pure returns (bytes32) {
        return a < b ? keccak256(abi.encodePacked(a, b)) : keccak256(abi.encodePacked(b, a));
    }

    // ---------------------------------------------------------------
    // Funciones YA HECHAS (no modificar)
    // ---------------------------------------------------------------
    function hashDocumento(string calldata documentoCanonico) external pure override returns (bytes32) {
        return keccak256(bytes(documentoCanonico));
    }

    function compromiso(bytes32 sal, bytes32 hashDoc) external pure override returns (bytes32) {
        return ConstantesUBO.compromiso(sal, hashDoc);
    }

    function hojaLote(bytes10 localizador, bytes32 compromiso_) external pure override returns (bytes32) {
        return ConstantesUBO.hojaLote(localizador, compromiso_);
    }
}

contracts/interfaces/IHerramientasSello..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title IHerramientasSello — Interfaz del Módulo C (Curso C)
/// @notice Cálculos auxiliares del sistema, escritos en Solidity como funciones `pure`:
///         no leen ni escriben estado y se pueden llamar gratis desde Remix.
///         Sustituyen a lo que antes se pedía programar en JavaScript.
/// @dev    NO MODIFICAR sin acuerdo de los tres cursos.
interface IHerramientasSello {
    /// @notice ¿Sirve este byte para elegir un símbolo sin sesgo?
    /// @dev El alfabeto tiene 36 símbolos y un byte toma 256 valores. Solo se aceptan
    ///      los bytes que se reparten de forma pareja entre los 36 símbolos.
    function byteAceptado(uint8 b) external pure returns (bool);

    /// @notice Símbolo del alfabeto "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ" que
    ///         corresponde a un byte ACEPTADO. Debe revertir si el byte no es aceptado.
    function simboloDe(uint8 b) external pure returns (bytes1);

    /// @notice Deriva un localizador válido (10 símbolos del alfabeto) a partir de una
    ///         semilla aleatoria de 32 bytes, sin sesgo de módulo.
    /// @dev Determinista: la misma semilla produce siempre el mismo localizador.
    ///      Fuente de bytes: h = keccak256(abi.encode(semilla)); se recorren sus 32 bytes
    ///      en orden; los no aceptados se descartan; si se agotan, h = keccak256(abi.encode(h)).
    function derivarLocalizador(bytes32 semilla) external pure returns (bytes10);

    /// @notice Raíz de Merkle de una lista de hojas, compatible con MerkleProof de OpenZeppelin.
    /// @dev Pares ORDENADOS (el menor primero) y keccak256(abi.encodePacked(a, b)).
    ///      Si un nivel tiene un número impar de nodos, el último sube sin emparejar.
    ///      Debe revertir si la lista está vacía.
    function raizDeMerkle(bytes32[] calldata hojas) external pure returns (bytes32);

    /// @notice keccak256 del texto del documento (ya canonicalizado).
    function hashDocumento(string calldata documentoCanonico) external pure returns (bytes32);

    /// @notice Compromiso = keccak256(abi.encode(sal, hashDocumento)).
    function compromiso(bytes32 sal, bytes32 hashDoc) external pure returns (bytes32);

    /// @notice Hoja del árbol de una ceremonia (doble hash).
    function hojaLote(bytes10 localizador, bytes32 compromiso_) external pure returns (bytes32);
}

contracts/simulacros/SimRegistroEmisores.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../interfaces/IRegistroEmisores.sol";

/// @title SimRegistroEmisores — Simulacro del Módulo A
/// @notice Lo usan los Cursos B y C mientras el Curso A desarrolla el real.
/// @dev    SIMPLIFICACIONES (el módulo real NO puede tenerlas):
///         - No hay multifirma: cualquiera puede autorizar o revocar.
///         - Solo recuerda el ÚLTIMO periodo de cada (emisor, facultad).
///         - fijarPeriodo() permite fabricar periodos pasados para las pruebas.
contract SimRegistroEmisores is IRegistroEmisores {
    struct Periodo {
        uint256 desde;
        uint256 hasta; // 0 = abierto
        bool existe;
    }

    mapping(address => mapping(bytes32 => Periodo)) private _periodo;

    function autorizarEmisor(address emisor, bytes32 facultad) external override {
        _periodo[emisor][facultad] = Periodo(block.timestamp, 0, true);
        emit EmisorAutorizado(emisor, facultad, block.timestamp);
    }

    function revocarEmisor(address emisor, bytes32 facultad) external override {
        Periodo storage p = _periodo[emisor][facultad];
        require(p.existe && p.hasta == 0, "Sim: no autorizado");
        p.hasta = block.timestamp;
        emit EmisorRevocado(emisor, facultad, block.timestamp);
    }

    /// @notice SOLO PARA PRUEBAS: fija directamente un periodo [desde, hasta).
    function fijarPeriodo(address emisor, bytes32 facultad, uint256 desde, uint256 hasta) external {
        _periodo[emisor][facultad] = Periodo(desde, hasta, true);
    }

    function estaAutorizado(address emisor, bytes32 facultad) external view override returns (bool) {
        Periodo storage p = _periodo[emisor][facultad];
        return p.existe && p.hasta == 0;
    }

    function estabaAutorizado(address emisor, bytes32 facultad, uint256 momento)
        external
        view
        override
        returns (bool)
    {
        Periodo storage p = _periodo[emisor][facultad];
        if (!p.existe || momento < p.desde) return false;
        return p.hasta == 0 || momento < p.hasta;
    }
}

contracts/simulacros/SimRegistroTitulos..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../interfaces/IRegistroTitulos.sol";
import "../comun/ConstantesUBO.sol";

/// @title SimRegistroTitulos — Simulacro del Módulo B
/// @notice Lo usa el Curso C mientras el Curso B desarrolla el real.
/// @dev    SIMPLIFICACIONES (el módulo real NO puede tenerlas):
///         - No consulta el registro de emisores: cualquiera puede emitir y cambiar estados.
///         - No valida el formato del localizador ni el tamaño del lote.
///         - fijarTitulo() permite fabricar cualquier título para las pruebas.
contract SimRegistroTitulos is IRegistroTitulos {
    mapping(bytes10 => Titulo) private _titulos;

    function emitir(bytes10 localizador, bytes32 facultad, bytes32 codigoPrograma, bytes32 compromiso_)
        public
        override
    {
        require(_titulos[localizador].estado == Estado.Inexistente, "Sim: ya existe");
        _titulos[localizador] = Titulo({
            compromiso: compromiso_,
            emisor: msg.sender,
            facultad: facultad,
            codigoPrograma: codigoPrograma,
            fechaEmision: uint64(block.timestamp),
            estado: Estado.Emitido,
            motivo: ConstantesUBO.MOTIVO_NINGUNO,
            rectificadoComo: bytes10(0)
        });
        emit TituloEmitido(localizador, facultad, compromiso_, msg.sender);
    }

    function emitirLote(
        bytes10[] calldata localizadores,
        bytes32 facultad,
        bytes32 codigoPrograma,
        bytes32[] calldata compromisos
    ) external override {
        require(localizadores.length == compromisos.length, "Sim: largos distintos");
        for (uint256 i = 0; i < localizadores.length; i++) {
            emitir(localizadores[i], facultad, codigoPrograma, compromisos[i]);
        }
    }

    function suspender(bytes10 localizador, uint8 motivo) external override {
        _cambiar(localizador, Estado.Suspendido, motivo);
    }

    function reactivar(bytes10 localizador) external override {
        _cambiar(localizador, Estado.Emitido, ConstantesUBO.MOTIVO_NINGUNO);
    }

    function revocar(bytes10 localizador, uint8 motivo) external override {
        _cambiar(localizador, Estado.Revocado, motivo);
    }

    function rectificar(bytes10 anterior, bytes10 nuevo, bytes32 nuevoCompromiso) external override {
        Titulo memory t = _titulos[anterior];
        emitir(nuevo, t.facultad, t.codigoPrograma, nuevoCompromiso);
        _cambiar(anterior, Estado.Revocado, ConstantesUBO.MOTIVO_RECTIFICACION);
        _titulos[anterior].rectificadoComo = nuevo;
        emit TituloRectificado(anterior, nuevo);
    }

    /// @notice SOLO PARA PRUEBAS: fija un título arbitrario.
    function fijarTitulo(bytes10 localizador, Titulo calldata titulo) external {
        _titulos[localizador] = titulo;
    }

    function obtenerTitulo(bytes10 localizador) external view override returns (Titulo memory) {
        return _titulos[localizador];
    }

    function _cambiar(bytes10 localizador, Estado nuevo, uint8 motivo) private {
        _titulos[localizador].estado = nuevo;
        _titulos[localizador].motivo = motivo;
        emit EstadoCambiado(localizador, nuevo, motivo);
    }
}

contracts/comun/ActorPruebas.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title ActorPruebas — Auxiliar para las pruebas unitarias de Remix
/// @notice En las pruebas de Remix, el contrato de prueba siempre llama con su
///         propia dirección. Para simular a varias personas (tres firmantes, dos
///         emisores, un titulado), se despliega un ActorPruebas por persona y se
///         llama «a través» de él.
/// @dev    Ejemplo:
///             ActorPruebas rector = new ActorPruebas();
///             rector.llamar(address(multifirma),
///                 abi.encodeCall(IMultifirmaUBO.confirmar, (0)));
///         Si la llamada interna revierte, llamar() revierte con el mismo error,
///         por lo que puede usarse dentro de try/catch.
contract ActorPruebas {
    function llamar(address destino, bytes calldata datos) external returns (bytes memory resultado) {
        (bool ok, bytes memory ret) = destino.call(datos);
        if (!ok) {
            assembly {
                revert(add(ret, 32), mload(ret))
            }
        }
        return ret;
    }

    /// @notice Versión que no revierte: devuelve si la llamada tuvo éxito.
    function intentar(address destino, bytes calldata datos) external returns (bool ok) {
        (ok,) = destino.call(datos);
    }
}

contracts/moduloC/VerificadorUBO.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../interfaces/IVerificadorUBO.sol";
import "../interfaces/IRegistroTitulos.sol";
import "../interfaces/IRegistroEmisores.sol";

/// @title VerificadorUBO, Módulo C (Curso C)
/// @notice Aplica la regla RN-06 y devuelve un veredicto.
/// @dev    Orden OBLIGATORIO (el primero que falla decide):
///         1) Inexistente  2) EmisorNoAutorizado (en la FECHA DE EMISIÓN)
///         3) Revocado     4) Suspendido   5) DocumentoAlterado   6) Valido
contract VerificadorUBO is IVerificadorUBO {
    IRegistroTitulos public immutable titulos;
    IRegistroEmisores public immutable registro;

    constructor(address titulos_, address registro_) {
        titulos = IRegistroTitulos(titulos_);
        registro = IRegistroEmisores(registro_);
    }

    function verificar(bytes10 localizador, bytes32 compromisoRecalculado)
        external
        view
        override
        returns (Veredicto)
    {
        return _veredicto(titulos.obtenerTitulo(localizador), compromisoRecalculado);
    }

    /// @notice Versión explicativa para el verificador humano.
    /// @dev    Devuelve el veredicto y un texto claro en español para un empleador.
    ///         Si el título fue rectificado, indica el nuevo localizador (rectificadoComo).
    function verificarConExplicacion(bytes10 localizador, bytes32 compromisoRecalculado)
        external
        view
        returns (Veredicto veredicto, string memory explicacion)
    {
        IRegistroTitulos.Titulo memory t = titulos.obtenerTitulo(localizador);
        veredicto = _veredicto(t, compromisoRecalculado);

        if (veredicto == Veredicto.Valido) {
            explicacion = "Titulo valido emitido por la UBO";
        } else if (veredicto == Veredicto.Inexistente) {
            explicacion = "No existe un titulo registrado con ese localizador";
        } else if (veredicto == Veredicto.EmisorNoAutorizado) {
            explicacion = "El emisor no estaba autorizado en la facultad en la fecha de emision";
        } else if (veredicto == Veredicto.Revocado) {
            if (t.rectificadoComo != bytes10(0)) {
                explicacion = string.concat(
                    "Titulo revocado por rectificacion. Pida el documento con el nuevo localizador: ",
                    _texto(t.rectificadoComo)
                );
            } else {
                explicacion = "Titulo revocado: no es valido";
            }
        } else if (veredicto == Veredicto.Suspendido) {
            explicacion = "Titulo suspendido temporalmente: no es valido por ahora";
        } else {
            explicacion = "El documento presentado no coincide con el registrado: fue alterado";
        }
    }

    /// @dev Aplica las seis comprobaciones en el orden obligatorio.
    ///      Se consulta estabaAutorizado (histórica, en la fecha de emisión), no estaAutorizado.
    function _veredicto(IRegistroTitulos.Titulo memory t, bytes32 compromisoRecalculado)
        internal
        view
        returns (Veredicto)
    {
        if (t.estado == IRegistroTitulos.Estado.Inexistente) return Veredicto.Inexistente;
        if (!registro.estabaAutorizado(t.emisor, t.facultad, t.fechaEmision)) {
            return Veredicto.EmisorNoAutorizado;
        }
        if (t.estado == IRegistroTitulos.Estado.Revocado) return Veredicto.Revocado;
        if (t.estado == IRegistroTitulos.Estado.Suspendido) return Veredicto.Suspendido;
        if (t.compromiso != compromisoRecalculado) return Veredicto.DocumentoAlterado;
        return Veredicto.Valido;
    }

    /// @dev Convierte un bytes10 (ASCII) en texto, ignorando bytes nulos.
    function _texto(bytes10 loc) internal pure returns (string memory) {
        bytes memory out = new bytes(10);
        uint256 n;
        for (uint256 i = 0; i < 10; i++) {
            if (loc[i] != 0) out[n++] = loc[i];
        }
        assembly { mstore(out, n) }
        return string(out);
    }
}

