// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../interfaces/IHerramientasSello.sol";
import "../comun/ConstantesUBO.sol";

/// @title HerramientasSello — PLANTILLA del Módulo C (Curso C)
/// @notice Cálculos auxiliares en Solidity. Todas las funciones son `pure`: se pueden
///         llamar gratis desde «Deploy & Run» de Remix, sin enviar transacciones.
/// @dev    Completar los TODO. Las tres últimas funciones ya están hechas.
contract HerramientasSello is IHerramientasSello {
    error ByteNoAceptado(uint8 b);
    error ListaVacia();

    /// @dev Los 36 símbolos permitidos, en orden. ALFABETO[i] devuelve el símbolo número i.
    bytes internal constant ALFABETO = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";

    // ---------------------------------------------------------------
    // Localizador sin sesgo de módulo
    // ---------------------------------------------------------------
    /// @dev 256 = 7 × 36 + 4. El mayor múltiplo de 36 que cabe en 256 es 252 (7 × 36),
    ///      así que se aceptan los bytes 0..251: cada símbolo recibe exactamente 7 bytes.
    function byteAceptado(uint8 b) public pure override returns (bool) {
        return b < 252;
    }

    function simboloDe(uint8 b) public pure override returns (bytes1) {
        if (!byteAceptado(b)) revert ByteNoAceptado(b);
        return ALFABETO[b % 36];
    }

    function derivarLocalizador(bytes32 semilla) external pure override returns (bytes10) {
        bytes memory resultado = new bytes(10);
        uint256 n = 0;
        bytes32 h = keccak256(abi.encode(semilla));
        while (n < 10) {
            for (uint256 i = 0; i < 32 && n < 10; i++) {
                uint8 b = uint8(h[i]);
                if (byteAceptado(b)) {
                    resultado[n++] = simboloDe(b);
                }
            }
            if (n < 10) h = keccak256(abi.encode(h));
        }
        return bytes10(resultado);
    }

    // ---------------------------------------------------------------
    // Raíz de Merkle
    // ---------------------------------------------------------------
    /// @dev Reduce nivel a nivel sobre la misma copia en memoria: el nodo i del nivel
    ///      siguiente se escribe en la posición i, que ya fue leída. Si sobra un nodo,
    ///      sube tal cual.
    function raizDeMerkle(bytes32[] calldata hojas) external pure override returns (bytes32) {
        uint256 n = hojas.length;
        if (n == 0) revert ListaVacia();
        bytes32[] memory nivel = hojas;
        while (n > 1) {
            uint256 m = 0;
            for (uint256 i = 0; i < n; i += 2) {
                nivel[m++] = i + 1 < n ? _hashPar(nivel[i], nivel[i + 1]) : nivel[i];
            }
            n = m;
        }
        return nivel[0];
    }

    /// @dev Hash de un par ordenado, igual que MerkleProof de OpenZeppelin. YA HECHA.
    function _hashPar(bytes32 a, bytes32 b) internal pure returns (bytes32) {
        return a < b ? keccak256(abi.encodePacked(a, b)) : keccak256(abi.encodePacked(b, a));
    }

    // ---------------------------------------------------------------
    // Funciones YA HECHAS (no modificar)
    // ---------------------------------------------------------------
    function hashDocumento(string calldata documentoCanonico) external pure override returns (bytes32) {
        return keccak256(bytes(documentoCanonico));
    }

    function compromiso(bytes32 sal, bytes32 hashDoc) external pure override returns (bytes32) {
        return ConstantesUBO.compromiso(sal, hashDoc);
    }

    function hojaLote(bytes10 localizador, bytes32 compromiso_) external pure override returns (bytes32) {
        return ConstantesUBO.hojaLote(localizador, compromiso_);
    }
}

contracts/interfaces/IHerramientasSello..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title IHerramientasSello — Interfaz del Módulo C (Curso C)
/// @notice Cálculos auxiliares del sistema, escritos en Solidity como funciones `pure`:
///         no leen ni escriben estado y se pueden llamar gratis desde Remix.
///         Sustituyen a lo que antes se pedía programar en JavaScript.
/// @dev    NO MODIFICAR sin acuerdo de los tres cursos.
interface IHerramientasSello {
    /// @notice ¿Sirve este byte para elegir un símbolo sin sesgo?
    /// @dev El alfabeto tiene 36 símbolos y un byte toma 256 valores. Solo se aceptan
    ///      los bytes que se reparten de forma pareja entre los 36 símbolos.
    function byteAceptado(uint8 b) external pure returns (bool);

    /// @notice Símbolo del alfabeto "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ" que
    ///         corresponde a un byte ACEPTADO. Debe revertir si el byte no es aceptado.
    function simboloDe(uint8 b) external pure returns (bytes1);

    /// @notice Deriva un localizador válido (10 símbolos del alfabeto) a partir de una
    ///         semilla aleatoria de 32 bytes, sin sesgo de módulo.
    /// @dev Determinista: la misma semilla produce siempre el mismo localizador.
    ///      Fuente de bytes: h = keccak256(abi.encode(semilla)); se recorren sus 32 bytes
    ///      en orden; los no aceptados se descartan; si se agotan, h = keccak256(abi.encode(h)).
    function derivarLocalizador(bytes32 semilla) external pure returns (bytes10);

    /// @notice Raíz de Merkle de una lista de hojas, compatible con MerkleProof de OpenZeppelin.
    /// @dev Pares ORDENADOS (el menor primero) y keccak256(abi.encodePacked(a, b)).
    ///      Si un nivel tiene un número impar de nodos, el último sube sin emparejar.
    ///      Debe revertir si la lista está vacía.
    function raizDeMerkle(bytes32[] calldata hojas) external pure returns (bytes32);

    /// @notice keccak256 del texto del documento (ya canonicalizado).
    function hashDocumento(string calldata documentoCanonico) external pure returns (bytes32);

    /// @notice Compromiso = keccak256(abi.encode(sal, hashDocumento)).
    function compromiso(bytes32 sal, bytes32 hashDoc) external pure returns (bytes32);

    /// @notice Hoja del árbol de una ceremonia (doble hash).
    function hojaLote(bytes10 localizador, bytes32 compromiso_) external pure returns (bytes32);
}

contracts/comun/ConstantesUBO.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title ConstantesUBO — Valores comunes a los tres módulos de Sello Libertador
/// @notice Uso: import "../comun/ConstantesUBO.sol";  y luego ConstantesUBO.ING
library ConstantesUBO {
    // ---------------------------------------------------------------
    // Facultades de la Universidad Bernardo O'Higgins
    // ---------------------------------------------------------------
    bytes32 internal constant ING = keccak256("ING"); // Ingeniería, Ciencia y Tecnología
    bytes32 internal constant HUM = keccak256("HUM"); // Ciencias Humanas
    bytes32 internal constant SAL = keccak256("SAL"); // Ciencias de la Salud
    bytes32 internal constant MED = keccak256("MED"); // Ciencias Médicas

    // ---------------------------------------------------------------
    // Códigos de motivo de suspensión o revocación (campo Titulo.motivo)
    // ---------------------------------------------------------------
    uint8 internal constant MOTIVO_NINGUNO = 0;
    uint8 internal constant MOTIVO_ERROR_ADMINISTRATIVO = 1;
    uint8 internal constant MOTIVO_FRAUDE = 2;
    uint8 internal constant MOTIVO_RESOLUCION_JUDICIAL = 3;
    uint8 internal constant MOTIVO_RECTIFICACION = 4;
    uint8 internal constant MOTIVO_EN_INVESTIGACION = 5; // típico de una suspensión

    // ---------------------------------------------------------------
    // Límites
    // ---------------------------------------------------------------
    /// @notice Máximo de títulos por llamada a emitirLote (evita DoS por límite de gas).
    uint256 internal constant MAX_LOTE = 50;

    /// @notice ¿Es una facultad reconocida?
    function esFacultadValida(bytes32 facultad) internal pure returns (bool) {
        return facultad == ING || facultad == HUM || facultad == SAL || facultad == MED;
    }

    /// @notice Compromiso criptográfico común a todo el sistema.
    /// @param sal           32 bytes aleatorios, incluidos en el documento cifrado del enlace.
    /// @param hashDocumento keccak256 del documento de la credencial en JSON
    ///                      canonicalizado (RFC 8785).
    function compromiso(bytes32 sal, bytes32 hashDocumento) internal pure returns (bytes32) {
        return keccak256(abi.encode(sal, hashDocumento));
    }

    /// @notice Hoja del árbol de Merkle de una ceremonia (ver IAnclajeLotes).
    function hojaLote(bytes10 localizador, bytes32 compromiso_) internal pure returns (bytes32) {
        return keccak256(bytes.concat(keccak256(abi.encode(localizador, compromiso_))));
    }
}

contracts/moduloC/AnclajeLotes.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts@5.1.0/utils/cryptography/MerkleProof.sol";
import "../interfaces/IAnclajeLotes.sol";
import "../interfaces/IRegistroEmisores.sol";
import "../comun/ConstantesUBO.sol";

/// @title AnclajeLotes — PLANTILLA del Módulo C (Curso C)
/// @notice MODO ECONÓMICO, alternativo a RegistroTitulos: ancla la raíz de Merkle de una
///         ceremonia completa en UNA transacción, sin guardar cada título en la cadena.
///         No se usa sobre los mismos títulos que ya están en RegistroTitulos: es otra
///         forma de emitir, más barata y con menos funciones (no hay estado por título).
/// @dev    Completar los TODO. Requisitos mínimos:
///         - Solo emisores autorizados AHORA en la facultad.
///         - Rechazar raíz vacía y raíces repetidas.
///         - Hoja = ConstantesUBO.hojaLote(localizador, compromiso).
///         - Verificación con MerkleProof.verify (pares ordenados).
contract AnclajeLotes is IAnclajeLotes {
    error NoAutorizado(address cuenta, bytes32 facultad);
    error RaizInvalida();
    error RaizDuplicada(bytes32 raiz);
    error LoteInexistente(uint256 loteId);

    struct Lote {
        bytes32 raiz;
        bytes32 facultad;
        bytes32 idCeremonia;
        address emisor;
        uint64 fecha;
    }

    IRegistroEmisores public immutable registro;
    mapping(uint256 => Lote) private _lotes;
    mapping(bytes32 => bool) private _raizUsada;
    uint256 private _siguienteId = 1;

    constructor(address registro_) {
        registro = IRegistroEmisores(registro_);
    }

    /// @dev Orden: autorización (estaAutorizado, el presente), raíz vacía, raíz repetida.
    ///      Se escribe el estado solo después de validar todo.
    function anclarLote(bytes32 raiz, bytes32 facultad, bytes32 idCeremonia)
        external
        override
        returns (uint256 loteId)
    {
        if (!registro.estaAutorizado(msg.sender, facultad)) revert NoAutorizado(msg.sender, facultad);
        if (raiz == bytes32(0)) revert RaizInvalida();
        if (_raizUsada[raiz]) revert RaizDuplicada(raiz);

        loteId = _siguienteId++;
        _raizUsada[raiz] = true;
        _lotes[loteId] = Lote(raiz, facultad, idCeremonia, msg.sender, uint64(block.timestamp));
        emit LoteAnclado(loteId, facultad, raiz, idCeremonia, msg.sender);
    }

    /// @dev Un lote existe si tiene raíz: anclarLote nunca guarda una raíz vacía.
    function verificarInclusion(
        uint256 loteId,
        bytes10 localizador,
        bytes32 compromiso,
        bytes32[] calldata prueba
    ) external view override returns (bool) {
        bytes32 raiz = _lotes[loteId].raiz;
        if (raiz == bytes32(0)) revert LoteInexistente(loteId);
        return MerkleProof.verifyCalldata(prueba, raiz, ConstantesUBO.hojaLote(localizador, compromiso));
    }

    function obtenerLote(uint256 loteId) external view returns (Lote memory) {
        return _lotes[loteId];
    }
}

