// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../interfaces/IRegistroTitulos.sol";
import "../comun/ConstantesUBO.sol";

/// @title SimRegistroTitulos — Simulacro del Módulo B
/// @notice Lo usa el Curso C mientras el Curso B desarrolla el real.
/// @dev    SIMPLIFICACIONES (el módulo real NO puede tenerlas):
///         - No consulta el registro de emisores: cualquiera puede emitir y cambiar estados.
///         - No valida el formato del localizador ni el tamaño del lote.
///         - fijarTitulo() permite fabricar cualquier título para las pruebas.
contract SimRegistroTitulos is IRegistroTitulos {
    mapping(bytes10 => Titulo) private _titulos;

    function emitir(bytes10 localizador, bytes32 facultad, bytes32 codigoPrograma, bytes32 compromiso_)
        public
        override
    {
        require(_titulos[localizador].estado == Estado.Inexistente, "Sim: ya existe");
        _titulos[localizador] = Titulo({
            compromiso: compromiso_,
            emisor: msg.sender,
            facultad: facultad,
            codigoPrograma: codigoPrograma,
            fechaEmision: uint64(block.timestamp),
            estado: Estado.Emitido,
            motivo: ConstantesUBO.MOTIVO_NINGUNO,
            rectificadoComo: bytes10(0)
        });
        emit TituloEmitido(localizador, facultad, compromiso_, msg.sender);
    }

    function emitirLote(
        bytes10[] calldata localizadores,
        bytes32 facultad,
        bytes32 codigoPrograma,
        bytes32[] calldata compromisos
    ) external override {
        require(localizadores.length == compromisos.length, "Sim: largos distintos");
        for (uint256 i = 0; i < localizadores.length; i++) {
            emitir(localizadores[i], facultad, codigoPrograma, compromisos[i]);
        }
    }

    function suspender(bytes10 localizador, uint8 motivo) external override {
        _cambiar(localizador, Estado.Suspendido, motivo);
    }

    function reactivar(bytes10 localizador) external override {
        _cambiar(localizador, Estado.Emitido, ConstantesUBO.MOTIVO_NINGUNO);
    }

    function revocar(bytes10 localizador, uint8 motivo) external override {
        _cambiar(localizador, Estado.Revocado, motivo);
    }

    function rectificar(bytes10 anterior, bytes10 nuevo, bytes32 nuevoCompromiso) external override {
        Titulo memory t = _titulos[anterior];
        emitir(nuevo, t.facultad, t.codigoPrograma, nuevoCompromiso);
        _cambiar(anterior, Estado.Revocado, ConstantesUBO.MOTIVO_RECTIFICACION);
        _titulos[anterior].rectificadoComo = nuevo;
        emit TituloRectificado(anterior, nuevo);
    }

    /// @notice SOLO PARA PRUEBAS: fija un título arbitrario.
    function fijarTitulo(bytes10 localizador, Titulo calldata titulo) external {
        _titulos[localizador] = titulo;
    }

    function obtenerTitulo(bytes10 localizador) external view override returns (Titulo memory) {
        return _titulos[localizador];
    }

    function _cambiar(bytes10 localizador, Estado nuevo, uint8 motivo) private {
        _titulos[localizador].estado = nuevo;
        _titulos[localizador].motivo = motivo;
        emit EstadoCambiado(localizador, nuevo, motivo);
    }
}

contracts/interfaces/IRegistroTitulos.so.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title IRegistroTitulos — Interfaz del Módulo B (Curso B)
/// @notice Registro de los títulos de la UBO. El titulado NO necesita billetera:
///         cada título se identifica con un LOCALIZADOR público de 10 caracteres
///         (p. ej. "U0ZSA8QPFN") y en la cadena solo se guarda un compromiso
///         criptográfico del documento, nunca datos personales.
/// @dev    NO MODIFICAR sin acuerdo de los tres cursos.
///         Localizador válido: exactamente 10 caracteres en [0-9A-Z] (ASCII),
///         guardados en un bytes10. Ejemplo: bytes10("U0ZSA8QPFN").
///         Los códigos de motivo están en contracts/comun/ConstantesUBO.sol.
interface IRegistroTitulos {
    enum Estado {
        Inexistente, // 0: el localizador nunca se registró
        Emitido,     // 1: vigente
        Suspendido,  // 2: temporalmente no válido
        Revocado     // 3: no válido de forma definitiva
    }

    struct Titulo {
        bytes32 compromiso;     // keccak256(abi.encode(sal, hashDocumento))
        address emisor;         // dirección del funcionario que lo emitió
        bytes32 facultad;       // p. ej. keccak256("ING")
        bytes32 codigoPrograma; // p. ej. keccak256("ING-INFORMATICA"); no personal
        uint64 fechaEmision;    // block.timestamp de la emisión
        Estado estado;
        uint8 motivo;           // 0 si no hay motivo; ver ConstantesUBO
        bytes10 rectificadoComo; // localizador que lo sustituye; vacío si ninguno
    }

    event TituloEmitido(
        bytes10 indexed localizador,
        bytes32 indexed facultad,
        bytes32 compromiso,
        address emisor
    );
    event EstadoCambiado(bytes10 indexed localizador, Estado estadoNuevo, uint8 motivo);
    event TituloRectificado(bytes10 indexed anterior, bytes10 indexed nuevo);

    /// @notice Registra un título. Solo un emisor autorizado AHORA en `facultad`.
    /// @dev Debe revertir si: el localizador no es válido o ya existe,
    ///      o compromiso = bytes32(0).
    function emitir(bytes10 localizador, bytes32 facultad, bytes32 codigoPrograma, bytes32 compromiso)
        external;

    /// @notice Registra varios títulos de una misma facultad y programa en una transacción.
    /// @dev Debe revertir si: los arreglos tienen distinto largo, están vacíos o
    ///      superan ConstantesUBO.MAX_LOTE; o si cualquier título es inválido
    ///      (en ese caso NO se registra ninguno: todo o nada).
    function emitirLote(
        bytes10[] calldata localizadores,
        bytes32 facultad,
        bytes32 codigoPrograma,
        bytes32[] calldata compromisos
    ) external;

    /// @notice Emitido -> Suspendido. Solo emisor autorizado de la MISMA facultad.
    function suspender(bytes10 localizador, uint8 motivo) external;

    /// @notice Suspendido -> Emitido. Solo emisor autorizado de la MISMA facultad.
    function reactivar(bytes10 localizador) external;

    /// @notice Emitido o Suspendido -> Revocado (definitivo). Solo emisor de la MISMA facultad.
    function revocar(bytes10 localizador, uint8 motivo) external;

    /// @notice Corrige un título con error: revoca `anterior` con MOTIVO_RECTIFICACION y
    ///         registra `nuevo` con la misma facultad y programa y `nuevoCompromiso`.
    function rectificar(bytes10 anterior, bytes10 nuevo, bytes32 nuevoCompromiso) external;

    /// @notice Devuelve el título. Si no existe, devuelve uno vacío con estado
    ///         Inexistente (NO revierte).
    function obtenerTitulo(bytes10 localizador) external view returns (Titulo memory);
}

contracts/comun/ConstantesUBO.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title ConstantesUBO — Valores comunes a los tres módulos de Sello Libertador
/// @notice Uso: import "../comun/ConstantesUBO.sol";  y luego ConstantesUBO.ING
library ConstantesUBO {
    // ---------------------------------------------------------------
    // Facultades de la Universidad Bernardo O'Higgins
    // ---------------------------------------------------------------
    bytes32 internal constant ING = keccak256("ING"); // Ingeniería, Ciencia y Tecnología
    bytes32 internal constant HUM = keccak256("HUM"); // Ciencias Humanas
    bytes32 internal constant SAL = keccak256("SAL"); // Ciencias de la Salud
    bytes32 internal constant MED = keccak256("MED"); // Ciencias Médicas

    // ---------------------------------------------------------------
    // Códigos de motivo de suspensión o revocación (campo Titulo.motivo)
    // ---------------------------------------------------------------
    uint8 internal constant MOTIVO_NINGUNO = 0;
    uint8 internal constant MOTIVO_ERROR_ADMINISTRATIVO = 1;
    uint8 internal constant MOTIVO_FRAUDE = 2;
    uint8 internal constant MOTIVO_RESOLUCION_JUDICIAL = 3;
    uint8 internal constant MOTIVO_RECTIFICACION = 4;
    uint8 internal constant MOTIVO_EN_INVESTIGACION = 5; // típico de una suspensión

    // ---------------------------------------------------------------
    // Límites
    // ---------------------------------------------------------------
    /// @notice Máximo de títulos por llamada a emitirLote (evita DoS por límite de gas).
    uint256 internal constant MAX_LOTE = 50;

    /// @notice ¿Es una facultad reconocida?
    function esFacultadValida(bytes32 facultad) internal pure returns (bool) {
        return facultad == ING || facultad == HUM || facultad == SAL || facultad == MED;
    }

    /// @notice Compromiso criptográfico común a todo el sistema.
    /// @param sal           32 bytes aleatorios, incluidos en el documento cifrado del enlace.
    /// @param hashDocumento keccak256 del documento de la credencial en JSON
    ///                      canonicalizado (RFC 8785).
    function compromiso(bytes32 sal, bytes32 hashDocumento) internal pure returns (bytes32) {
        return keccak256(abi.encode(sal, hashDocumento));
    }

    /// @notice Hoja del árbol de Merkle de una ceremonia (ver IAnclajeLotes).
    function hojaLote(bytes10 localizador, bytes32 compromiso_) internal pure returns (bytes32) {
        return keccak256(bytes.concat(keccak256(abi.encode(localizador, compromiso_))));
    }
}

contracts/simulacros/SimRegistroEmisores.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../interfaces/IRegistroEmisores.sol";

/// @title SimRegistroEmisores — Simulacro del Módulo A
/// @notice Lo usan los Cursos B y C mientras el Curso A desarrolla el real.
/// @dev    SIMPLIFICACIONES (el módulo real NO puede tenerlas):
///         - No hay multifirma: cualquiera puede autorizar o revocar.
///         - Solo recuerda el ÚLTIMO periodo de cada (emisor, facultad).
///         - fijarPeriodo() permite fabricar periodos pasados para las pruebas.
contract SimRegistroEmisores is IRegistroEmisores {
    struct Periodo {
        uint256 desde;
        uint256 hasta; // 0 = abierto
        bool existe;
    }

    mapping(address => mapping(bytes32 => Periodo)) private _periodo;

    function autorizarEmisor(address emisor, bytes32 facultad) external override {
        _periodo[emisor][facultad] = Periodo(block.timestamp, 0, true);
        emit EmisorAutorizado(emisor, facultad, block.timestamp);
    }

    function revocarEmisor(address emisor, bytes32 facultad) external override {
        Periodo storage p = _periodo[emisor][facultad];
        require(p.existe && p.hasta == 0, "Sim: no autorizado");
        p.hasta = block.timestamp;
        emit EmisorRevocado(emisor, facultad, block.timestamp);
    }

    /// @notice SOLO PARA PRUEBAS: fija directamente un periodo [desde, hasta).
    function fijarPeriodo(address emisor, bytes32 facultad, uint256 desde, uint256 hasta) external {
        _periodo[emisor][facultad] = Periodo(desde, hasta, true);
    }

    function estaAutorizado(address emisor, bytes32 facultad) external view override returns (bool) {
        Periodo storage p = _periodo[emisor][facultad];
        return p.existe && p.hasta == 0;
    }

    function estabaAutorizado(address emisor, bytes32 facultad, uint256 momento)
        external
        view
        override
        returns (bool)
    {
        Periodo storage p = _periodo[emisor][facultad];
        if (!p.existe || momento < p.desde) return false;
        return p.hasta == 0 || momento < p.hasta;
    }
}

contracts/interfaces/IRegistroEmisores.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title IRegistroEmisores — Interfaz del Módulo A (Curso A)
/// @notice Registro de las direcciones autorizadas para emitir títulos en
///         nombre de la UBO, por facultad, con memoria histórica.
/// @dev    NO MODIFICAR sin acuerdo de los tres cursos.
interface IRegistroEmisores {
    /// @notice Se emite cuando la administración autoriza a un emisor en una facultad.
    event EmisorAutorizado(address indexed emisor, bytes32 indexed facultad, uint256 desde);

    /// @notice Se emite cuando la administración retira la autorización.
    event EmisorRevocado(address indexed emisor, bytes32 indexed facultad, uint256 hasta);

    /// @notice Autoriza a `emisor` en `facultad`. Solo la administración (multifirma).
    /// @dev Debe revertir si el emisor ya está autorizado en esa facultad.
    function autorizarEmisor(address emisor, bytes32 facultad) external;

    /// @notice Retira la autorización de `emisor` en `facultad`. Solo la administración.
    /// @dev Debe revertir si el emisor no está autorizado en esa facultad.
    function revocarEmisor(address emisor, bytes32 facultad) external;

    /// @notice ¿Está autorizado AHORA `emisor` en `facultad`?
    function estaAutorizado(address emisor, bytes32 facultad) external view returns (bool);

    /// @notice ¿Estaba autorizado `emisor` en `facultad` en el instante `momento`
    ///         (marca de tiempo Unix, en segundos)?
    /// @dev Un periodo de autorización es el intervalo [desde, hasta):
    ///      incluye `desde` y excluye `hasta`. Un periodo abierto tiene hasta = 0.
    function estabaAutorizado(address emisor, bytes32 facultad, uint256 momento)
        external
        view
        returns (bool);
}
